//! Original governance struct order with immutable per-member collections.
//! Cold construction consumes only the actual qualified row JSON. Ordinary
//! updates never deserialize that complete row or clone its historical maps.
use super::*;
use super::original_rows::{OriginalProjectionRowsDataV1,OriginalProjectionRowDataV1};
use oasis7_world_state::incremental_governance_records::{GovernanceRecordKindV1 as Kind,GovernanceColumnV1 as Column,GovernanceCollectionV1 as Collection};
use oasis7_world_state::{GovernanceIdentityStatus,GovernanceProposalStatus,GovernanceVoteWeightSnapshotState,GovernanceVoteBallotState};
use serde::Serialize;
use std::{cell::RefCell,mem::size_of,sync::Arc};
pub(super) struct Scalar{value:serde_json::Value,_fee:MemoryReservation}
impl Scalar{pub(super) fn value(&self)->&serde_json::Value{&self.value}}
pub(super) struct OriginalGovernanceRecordDataV1{kind:Kind,scalars:[Option<Arc<Scalar>>;23],collections:[Arc<OriginalProjectionRowsDataV1>;4],_fee:MemoryReservation}
#[derive(Debug)]struct CodecCause{error:serde_json::Error,_fee:MemoryReservation}
impl std::fmt::Display for CodecCause{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{self.error.fmt(f)}}impl std::error::Error for CodecCause{}
fn reserve(common:&mut FormalBoundedContextV1<'_>,n:usize)->Result<MemoryReservation,BodyMutationError>{common.charge(1,n as u64).map_err(paid)?;common.memory().reserve(n,MemoryClass::Ordinary).map_err(ValueTreeError::Memory).map_err(Into::into)}
fn slot(column:Column)->usize{Column::ALL.into_iter().position(|c|c==column).expect("closed governance column")}
fn collection_slot(column:Collection)->usize{match column{Collection::Options=>0,Collection::Snapshot=>1,Collection::Ballots=>2,Collection::Tallies=>3}}
pub(super) fn scalar(value:serde_json::Value,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Scalar>,BodyMutationError>{let heap=match &value{serde_json::Value::String(v)=>v.capacity(),serde_json::Value::Null|serde_json::Value::Bool(_)|serde_json::Value::Number(_)=>0,_=>return Err(invalid("governance scalar container"))};let fee=reserve(common,heap.checked_add(size_of::<Scalar>()+2*size_of::<usize>()).ok_or_else(||invalid("governance scalar heap"))?)?;Ok(Arc::new(Scalar{value,_fee:fee}))}
fn json<T:serde::Serialize+?Sized>(value:&T,common:&mut FormalBoundedContextV1<'_>)->Result<ReservedValue<Vec<u8>>,BodyMutationError>{super::capture_projection_json_data_v1(value,common)}
fn row<K:oasis7_world_state::incremental_semantic_key::SemanticKeyV1+?Sized,V:serde::Serialize+?Sized>(key:&K,value:&V,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<OriginalProjectionRowDataV1>,BodyMutationError>{let semantic=super::initial::capture(common,|out|oasis7_world_state::incremental_semantic_key::write_semantic_key_v1(key,out).map_err(paid))?;let key=json(key,common)?;let value=json(value,common)?;OriginalProjectionRowDataV1::from_original_encoded_data_v1(semantic,key,value,common)}
impl OriginalGovernanceRecordDataV1{
 pub(super) fn empty_for_new_actual_entity_v1(kind:Kind,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;let mut collections=std::array::from_fn::<_,4,_>(|_|None);for slot in &mut collections{common.consume_steps(1).map_err(paid)?;*slot=Some(Arc::new(OriginalProjectionRowsDataV1::empty_data_v1(common)?));}Ok(Arc::new(Self{kind,scalars:std::array::from_fn(|_|None),collections:collections.map(|v|v.expect("four real new-entity empty containers")),_fee:fee}))}
 pub(super) fn validate_complete_v1(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{self.validate(common)?;common.consume_steps(23).map_err(paid)?;self.check_required_v1()}
 pub(super) fn from_original_qualified_json_v1(kind:Kind,bytes:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{
  // This one-time phase covers the original serde_json graph, its decoder's
  // error graph and temporary typed five/three-field member DTOs. The original
  // qualified source owner remains alive throughout this consuming fold.
  let phase=reserve(common,bytes.len().checked_mul(256).and_then(|n|n.checked_add(65536)).ok_or_else(||invalid("governance cold JSON graph"))?)?;common.charge(bytes.len() as u64,bytes.len() as u64).map_err(paid)?;let decoded=serde_json::from_slice::<serde_json::Value>(bytes);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};let serde_json::Value::Object(mut fields)=value else{return Err(invalid("governance original object"))};
  let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;let mut scalars=std::array::from_fn(|_|None);let mut collections=std::array::from_fn::<_,4,_>(|_|None);
  for column in Column::ALL{common.consume_steps(1).map_err(paid)?;if !column.accepts(kind){continue}let value=match fields.remove(column.name()){Some(v)=>v,None if column.nullable()=>serde_json::Value::Null,None=>return Err(invalid("governance original required scalar"))};scalars[slot(column)]=Some(scalar(value,common)?)}
  for column in Collection::ALL{common.consume_steps(1).map_err(paid)?;let mut rows=OriginalProjectionRowsDataV1::empty_data_v1(common)?;if column.accepts(kind){let value=fields.remove(column.name()).ok_or_else(||invalid("governance original required collection"))?;
   if column==Collection::Options{let serde_json::Value::Array(values)=value else{return Err(invalid("governance original options type"))};for (i,value)in values.into_iter().enumerate(){common.consume_steps(1).map_err(paid)?;let serde_json::Value::String(value)=value else{return Err(invalid("governance original option type"))};let index=u64::try_from(i).map_err(|_|invalid("governance original option ordinal"))?;let value=row(&index,&value,common)?;rows=rows.with_row_data_v1(value,common)?}}
   else{let serde_json::Value::Object(values)=value else{return Err(invalid("governance original member map type"))};for(key,value)in values{common.consume_steps(1).map_err(paid)?;let value=match column{
    Collection::Snapshot=>{let decoded=serde_json::from_value::<GovernanceVoteWeightSnapshotState>(value);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};row(&key,&value,common)?},
    Collection::Ballots=>{let decoded=serde_json::from_value::<GovernanceVoteBallotState>(value);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};row(&key,&value,common)?},
    Collection::Tallies=>{let value=value.as_u64().ok_or_else(||invalid("governance original tally type"))?;row(&key,&value,common)?},Collection::Options=>unreachable!()};rows=rows.with_row_data_v1(value,common)?}}
  }collections[collection_slot(column)]=Some(Arc::new(rows))}
  if !fields.is_empty(){return Err(invalid("governance original unknown field"))}let collections=collections.map(|v|v.expect("all four fixed collection slots"));let out=Self{kind,scalars,collections,_fee:fee};common.consume_steps(23).map_err(paid)?;out.check_required_v1()?;drop(phase);Ok(Arc::new(out))
 }
 pub(super) fn validate(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{common.consume_steps(1).map_err(paid)?;if !self._fee.uses_budget(common.memory()){return Err(invalid("governance resident pool"))}Ok(())}
 fn get(&self,column:Column)->Result<&serde_json::Value,BodyMutationError>{self.scalars[slot(column)].as_ref().map(|v|&v.value).ok_or_else(||invalid("governance resident scalar missing"))}
 fn text(&self,column:Column)->Result<&str,BodyMutationError>{self.get(column)?.as_str().ok_or_else(||invalid("governance resident string"))}
 fn uint(&self,column:Column)->Result<u64,BodyMutationError>{self.get(column)?.as_u64().ok_or_else(||invalid("governance resident unsigned"))}
 fn option_uint(&self,column:Column)->Result<Option<u64>,BodyMutationError>{let value=self.get(column)?;if value.is_null(){Ok(None)}else{value.as_u64().map(Some).ok_or_else(||invalid("governance resident optional unsigned"))}}
 fn option_text(&self,column:Column)->Result<Option<&str>,BodyMutationError>{let value=self.get(column)?;if value.is_null(){Ok(None)}else{value.as_str().map(Some).ok_or_else(||invalid("governance resident optional string"))}}
 fn identity_status(&self)->Result<GovernanceIdentityStatus,BodyMutationError>{match self.text(Column::IdentityStatus)?{"active"=>Ok(GovernanceIdentityStatus::Active),"frozen"=>Ok(GovernanceIdentityStatus::Frozen),"expelled"=>Ok(GovernanceIdentityStatus::Expelled),_=>Err(invalid("governance resident identity enum"))}}
 fn proposal_status(&self)->Result<GovernanceProposalStatus,BodyMutationError>{match self.text(Column::ProposalStatus)?{"open"=>Ok(GovernanceProposalStatus::Open),"passed"=>Ok(GovernanceProposalStatus::Passed),"rejected"=>Ok(GovernanceProposalStatus::Rejected),_=>Err(invalid("governance resident proposal enum"))}}
 fn check_required_v1(&self)->Result<(),BodyMutationError>{for column in Column::ALL{if column.accepts(self.kind){self.get(column)?;}}Ok(())}
 fn fork(&self,common:&mut FormalBoundedContextV1<'_>)->Result<Self,BodyMutationError>{self.validate(common)?;let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;common.consume_steps(27).map_err(paid)?;Ok(Self{kind:self.kind,scalars:self.scalars.clone(),collections:self.collections.clone(),_fee:fee})}
 pub(super) fn with_scalar_v1(&self,column:Column,bytes:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{if !column.accepts(self.kind){return Err(invalid("governance scalar owner"))}let phase=reserve(common,bytes.len().checked_mul(128).and_then(|n|n.checked_add(32768)).ok_or_else(||invalid("governance scalar graph"))?)?;common.charge(bytes.len()as u64,bytes.len()as u64).map_err(paid)?;let decoded=serde_json::from_slice(bytes);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};let value=scalar(value,common)?;let mut out=self.fork(common)?;out.scalars[slot(column)]=Some(value);Ok(Arc::new(out))}
 pub(super) fn with_collection_member_v1(&self,column:Collection,semantic:ReservedValue<Vec<u8>>,key:ReservedValue<Vec<u8>>,after:Option<ReservedValue<Vec<u8>>>,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{if !column.accepts(self.kind){return Err(invalid("governance collection owner"))}let mut out=self.fork(common)?;let before=&self.collections[collection_slot(column)];let rows=match after{Some(value)=>before.with_row_data_v1(OriginalProjectionRowDataV1::from_original_encoded_data_v1(semantic,key,value,common)?,common)?,None=>before.without_row_data_v1(&semantic,common)?};out.collections[collection_slot(column)]=Arc::new(rows);Ok(Arc::new(out))}
 pub(super) fn collection_rows_v1(&self,column:Collection,common:&mut FormalBoundedContextV1<'_>)->Result<&Arc<OriginalProjectionRowsDataV1>,BodyMutationError>{self.validate(common)?;if !column.accepts(self.kind){return Err(invalid("governance collection source kind"))}Ok(&self.collections[collection_slot(column)])}
 pub(super) fn collection_len_v1(&self,column:Collection,common:&mut FormalBoundedContextV1<'_>)->Result<usize,BodyMutationError>{self.validate(common)?;Ok(self.collections[collection_slot(column)].len())}
 pub(super) fn serialization_v1<'a,'b,'c>(&'a self,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>)->GovernanceSerialize<'a,'b,'c>{GovernanceSerialize{data:self,common,first}}
}
pub(super) struct GovernanceSerialize<'a,'b,'c>{data:&'a OriginalGovernanceRecordDataV1,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>}
impl serde::Serialize for GovernanceSerialize<'_,'_,'_>{fn serialize<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::Error as _;
 let checked=self.data.validate(&mut self.common.borrow_mut()).and_then(|_|self.common.borrow_mut().consume_steps(529).map_err(paid));if let Err(error)=checked{*self.first.borrow_mut()=Some(error);return Err(S::Error::custom("governance source meter"))}
 let data=self.data;macro_rules! get{($e:expr)=>{match $e{Ok(v)=>v,Err(error)=>{*self.first.borrow_mut()=Some(error);return Err(S::Error::custom("governance scalar source"))}}};}
 macro_rules! text{($c:ident)=>{get!(data.text(Column::$c))};}macro_rules! uint{($c:ident)=>{get!(data.uint(Column::$c))};}macro_rules! u32v{($c:ident)=>{get!(u32::try_from(uint!($c)).map_err(|_|invalid("governance u32 source")))};}
 match data.kind{
 Kind::Identity=>oasis7_world_state::GovernanceIdentityProjectionFieldsV1{agent_id:text!(AgentId),stake_locked:uint!(StakeLocked),warmup_until_tick:uint!(WarmupUntilTick),status:get!(data.identity_status()),slash_count:u32v!(SlashCount),updated_at:uint!(UpdatedAt)}.serialize(serializer),
 Kind::Proposal=>{let options=data.collections[0].original_value_sequence_serialization_v1(self.common,self.first);let snapshot=data.collections[1].original_map_serialization_v1(self.common,self.first);oasis7_world_state::GovernanceProposalProjectionFieldsV1{proposal_key:text!(ProposalKey),proposer_agent_id:text!(ProposerAgentId),title:text!(Title),description:text!(Description),options:&options,voting_window_ticks:uint!(VotingWindowTicks),quorum_weight:uint!(QuorumWeight),pass_threshold_bps:get!(u16::try_from(uint!(PassThresholdBps)).map_err(|_|invalid("governance u16 source"))),opened_at:uint!(OpenedAt),closes_at:uint!(ClosesAt),status:get!(data.proposal_status()),finalized_at:get!(data.option_uint(Column::FinalizedAt)),winning_option:get!(data.option_text(Column::WinningOption)),winning_weight:uint!(WinningWeight),total_weight_at_finalize:uint!(TotalWeightAtFinalize),snapshot_at_tick:uint!(SnapshotAtTick),vote_weight_snapshot:&snapshot}.serialize(serializer)},
 Kind::Vote=>{let ballots=data.collections[2].original_map_serialization_v1(self.common,self.first);let tallies=data.collections[3].original_map_serialization_v1(self.common,self.first);oasis7_world_state::GovernanceVoteProjectionFieldsV1{proposal_key:text!(ProposalKey),votes_by_agent:&ballots,tallies:&tallies,total_weight:uint!(TotalWeight),last_updated_at:uint!(LastUpdatedAt)}.serialize(serializer)}
 }
}}
